import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring, Easing } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type NetworkDiagramProps = Record<string, any>;

const NetworkDiagram: React.FC<NetworkDiagramProps> = ({
  backgroundColor = "#080808",
  transparentBackground = false,
  durationInSeconds = 5,
  centerGlowColor = "#ef4444",
  nodeGlowColor = "#22c55e",
  nodes = [
    { id: "1", boldText: "502", normalText: "Gateway Error" },
    { id: "2", boldText: "", normalText: "Domain verification" },
    { id: "3", boldText: "404", normalText: "Page Not Found" },
    { id: "4", boldText: "", normalText: "Performance questions" },
    { id: "5", boldText: "403", normalText: "Forbidden" },
    { id: "6", boldText: "500", normalText: "Internal Server Error" },
    { id: "7", boldText: "", normalText: "Site errors" }
  ]
}) => {

  {/* Load Google Fonts */ }
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */ }

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Constants (Logical 1920x1080 canvas)
  const logicalWidth = 1920;
  const logicalHeight = 1080;
  const scale = Math.min(width / logicalWidth, height / logicalHeight);
  const cx = logicalWidth / 2;
  const cy = logicalHeight / 2;

  // Animation Timings
  const totalFrames = durationInSeconds * fps;
  const entryDuration = Math.min(totalFrames * 0.7, totalFrames - 30);
  const centerAnimDuration = 15;
  const animTimePerNode = 30;
  
  const availableStaggerTime = Math.max(0, entryDuration - centerAnimDuration - animTimePerNode);
  const staggerInterval = nodes.length > 1 ? availableStaggerTime / (nodes.length - 1) : 0;

  // Auto-calculate positions to form a procedural radial layout since offsets were removed
  const calculatedNodes = useMemo(() => {
    return nodes.map((node, i) => {
      // Start from the top, distribute evenly
      const angle = (i / nodes.length) * Math.PI * 2 - Math.PI / 2;
      const radiusX = 600;
      const radiusY = 320;
      
      const xOffset = Math.cos(angle) * radiusX;
      const yOffset = Math.sin(angle) * radiusY;
      
      const curveType = Math.abs(xOffset) > Math.abs(yOffset) * 1.2 ? 'horizontal' : 'vertical';

      return {
        ...node,
        xOffset,
        yOffset,
        curveType
      };
    });
  }, [nodes]);

  // Center Node Animation
  const centerScale = spring({ frame: frame - 5, fps, config: { damping: 14, mass: 0.6 } });
  const pulse = 1 + Math.sin(frame / 12) * 0.15;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: 'hidden', alignItems: 'center', justifyContent: 'center' }}>
      <div style={{
        width: logicalWidth,
        height: logicalHeight,
        transform: `scale(${scale})`,
        position: 'relative',
        transformOrigin: 'center center',
        transition: 'none'
      }}>
        
        {/* Ambient Radial Background Glow */}
        <div style={{
          position: 'absolute',
          top: '50%', 
          left: '50%', 
          width: logicalWidth, 
          height: logicalHeight,
          transform: 'translate(-50%, -50%)',
          background: 'radial-gradient(circle at center, rgba(255,255,255,0.03) 0%, transparent 60%)',
          zIndex: 0
        }} />

        {/* Connection Paths */}
        <svg style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', zIndex: 1, overflow: 'visible' }}>
          <defs>
            {calculatedNodes.map(node => (
              <linearGradient key={`grad-${node.id}`} id={`grad-${node.id}`} x1={cx} y1={cy} x2={cx + node.xOffset} y2={cy + node.yOffset} gradientUnits="userSpaceOnUse">
                <stop offset="0%" stopColor={centerGlowColor} stopOpacity={1} />
                <stop offset="100%" stopColor={nodeGlowColor} stopOpacity={1} />
              </linearGradient>
            ))}
          </defs>

          {calculatedNodes.map((node, i) => {
            const badgeX = cx + node.xOffset;
            const badgeY = cy + node.yOffset;
            const dx = badgeX - cx;
            const dy = badgeY - cy;

            // Generate Path Data
            let d = "";
            if (node.curveType === 'horizontal') {
              d = `M ${cx} ${cy} C ${cx + dx/2} ${cy}, ${cx + dx/2} ${badgeY}, ${badgeX} ${badgeY}`;
            } else {
              d = `M ${cx} ${cy} C ${cx} ${cy + dy/2}, ${badgeX} ${cy + dy/2}, ${badgeX} ${badgeY}`;
            }

            // Estimate length perfectly for S-curves
            const estLength = Math.abs(dx) + Math.abs(dy) + 50;
            const pathStartFrame = centerAnimDuration + i * staggerInterval;
            
            const dashOffset = interpolate(frame, [pathStartFrame, pathStartFrame + 20], [estLength, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: Easing.out(Easing.cubic)
            });

            return (
              <path
                key={`path-${node.id}`}
                d={d}
                fill="none"
                stroke={`url(#grad-${node.id})`}
                strokeWidth={2}
                strokeDasharray={estLength}
                strokeDashoffset={dashOffset}
                strokeLinecap="round"
                style={{ transition: 'none' }}
              />
            );
          })}
        </svg>

        {/* Central Hub Node */}
        <div style={{
          position: 'absolute',
          left: cx,
          top: cy,
          width: 160,
          height: 160,
          transform: `translate(-50%, -50%) scale(${centerScale})`,
          backgroundColor: '#000000',
          borderRadius: 36,
          boxShadow: `0 0 ${60 * pulse}px 10px ${centerGlowColor}80, inset 0 0 20px rgba(255,255,255,0.05)`,
          border: `1px solid ${centerGlowColor}40`,
          zIndex: 10,
          transition: 'none'
        }} />

        {/* Status Badges */}
        <div style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', zIndex: 20 }}>
          {calculatedNodes.map((node, i) => {
            const badgeX = cx + node.xOffset;
            const badgeY = cy + node.yOffset;
            
            const pathStartFrame = centerAnimDuration + i * staggerInterval;
            const badgeStartFrame = pathStartFrame + 10; // Start scaling as path arrives

            const scale = spring({ frame: frame - badgeStartFrame, fps, config: { damping: 14 } });
            const opacity = interpolate(frame, [badgeStartFrame, badgeStartFrame + 10], [0, 1], { 
              extrapolateRight: "clamp", 
              extrapolateLeft: "clamp" 
            });

            return (
              <div key={node.id} style={{
                position: 'absolute',
                left: badgeX,
                top: badgeY,
                transform: `translate(-50%, -50%) scale(${scale})`,
                opacity,
                display: 'flex',
                alignItems: 'center',
                gap: 12,
                padding: '12px 18px',
                backgroundColor: '#161616',
                borderRadius: 16,
                border: `1px solid ${nodeGlowColor}40`,
                boxShadow: `0 4px 24px rgba(0,0,0,0.6), inset 0 0 12px ${nodeGlowColor}15`,
                color: '#fff',
                whiteSpace: 'nowrap',
                transition: 'none'
              }}>
                <div style={{
                  width: 24,
                  height: 24,
                  borderRadius: 6,
                  backgroundColor: nodeGlowColor,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexShrink: 0,
                }}>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                    <polyline points="20 6 9 17 4 12" />
                  </svg>
                </div>
                <div style={{ fontSize: 18, display: 'flex', gap: 6, alignItems: 'center' }}>
                  {node.boldText && <span style={{ fontWeight: 600, color: '#fff' }}>{node.boldText}</span>}
                  {node.normalText && <span style={{ fontWeight: 400, color: '#aaa' }}>{node.normalText}</span>}
                </div>
              </div>
            );
          })}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default NetworkDiagram;